package com.procurement.purchaseorder.specification;import com.procurement.purchaseorder.entity.*;import org.springframework.data.jpa.domain.Specification;public final class PurchaseOrderSpecification{private PurchaseOrderSpecification(){}public static Specification<PurchaseOrder>search(String k,Long v,PurchaseOrderStatus s){return(r,q,b)->{var p=b.conjunction();if(k!=null&&!k.isBlank())p=b.and(p,b.like(b.lower(r.get("poNumber")),"%"+k.toLowerCase()+"%"));if(v!=null)p=b.and(p,b.equal(r.get("vendor").get("id"),v));if(s!=null)p=b.and(p,b.equal(r.get("status"),s));return p;};}}
